#!/usr/bin/env python3
"""Generate core/lisp_eval_specials.mbt: the names of Maxima's special
variables (docs/index/specials.txt), which the Lisp evaluator binds
dynamically. Rerun after the contract (tools/analyze.py) changes."""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
names = sorted({l.strip() for l in open(os.path.join(ROOT, "docs/index/specials.txt")) if l.strip()})
out = [
    "// GENERATED by tools/gen_lisp_specials.py from docs/index/specials.txt.",
    "// The special variables of Maxima's Lisp code: the Lisp evaluator binds",
    "// them dynamically.",
    "",
    "///|",
    "let le__maxima_specials_text : String =",
]
for n in names:
    out.append("  #|" + n)
out += [
    "",
    "///|",
    "let le__maxima_specials_set : Ref[Set[String]?] = Ref(None)",
    "",
    "///|",
    "fn le__maxima_specials() -> Set[String] {",
    "  match le__maxima_specials_set.val {",
    "    Some(s) => s",
    "    None => {",
    "      let s : Set[String] = Set::new()",
    "      for line in le__maxima_specials_text.split(\"\\n\") {",
    "        if line.length() > 0 {",
    "          s.add(line.to_string())",
    "        }",
    "      }",
    "      le__maxima_specials_set.val = Some(s)",
    "      s",
    "    }",
    "  }",
    "}",
    "",
]
open(os.path.join(ROOT, "core/lisp_eval_specials.mbt"), "w").write("\n".join(out))
